package com.cyberyichen.bloub;
import android.media.*;
import android.os.*;
import android.util.Log;
import java.io.*;
import java.nio.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
/** Encodes the same PCM stream used by YAMNet, so only one microphone client is needed. */
final class MonitorAudio {
  private final HandlerThread thread=new HandlerThread("BloubMonitorAudio");private final Handler worker;private final MediaCodec encoder;private final MediaMuxer muxer;private final File file;private final AtomicInteger pending=new AtomicInteger();
  private volatile boolean finishing,failed;private volatile long originNs;private boolean muxerStarted;private int track=-1;private long lastPts=-1;private int samples;private final MediaCodec.BufferInfo info=new MediaCodec.BufferInfo();
  MonitorAudio(File file)throws Exception{this.file=file;MediaCodec candidate=MediaCodec.createEncoderByType("audio/mp4a-latm");MediaMuxer sink=null;try{MediaFormat format=MediaFormat.createAudioFormat("audio/mp4a-latm",16000,1);format.setInteger(MediaFormat.KEY_AAC_PROFILE,MediaCodecInfo.CodecProfileLevel.AACObjectLC);format.setInteger(MediaFormat.KEY_BIT_RATE,64000);format.setInteger(MediaFormat.KEY_MAX_INPUT_SIZE,4096);candidate.configure(format,null,null,MediaCodec.CONFIGURE_FLAG_ENCODE);candidate.start();sink=new MediaMuxer(file.getPath(),MediaMuxer.OutputFormat.MUXER_OUTPUT_MPEG_4);}catch(Exception e){candidate.release();if(sink!=null)sink.release();throw e;}encoder=candidate;muxer=sink;thread.start();worker=new Handler(thread.getLooper());}
  void start(long origin){originNs=origin;}
  void offer(short[] pcm,int n,long endNs){if(finishing||failed||originNs==0||pending.get()>=8)return;short[] data=java.util.Arrays.copyOf(pcm,n);pending.incrementAndGet();worker.post(()->{try{if(failed)return;long start=endNs-n*1000000000L/16000;int skip=(int)Math.max(0,Math.min(n,(originNs-start)*16000/1000000000L));if(skip>=n)return;int index=encoder.dequeueInputBuffer(10000);if(index<0){drain(false);index=encoder.dequeueInputBuffer(10000);}if(index<0)throw new IOException("Audio encoder unavailable");ByteBuffer input=encoder.getInputBuffer(index);input.clear();input.order(ByteOrder.LITTLE_ENDIAN);for(int i=skip;i<n;i++)input.putShort(data[i]);long pts=Math.max(0,(start+skip*1000000000L/16000-originNs)/1000);pts=Math.max(lastPts+1,pts);lastPts=pts;samples+=n-skip;encoder.queueInputBuffer(index,0,(n-skip)*2,pts,0);drain(false);}catch(Exception e){failed=true;Log.w("BloubMonitor","Audio encode",e);}finally{pending.decrementAndGet();}});}
  private void drain(boolean end)throws Exception{long deadline=android.os.SystemClock.elapsedRealtime()+3000;while(true){int output=encoder.dequeueOutputBuffer(info,end?10000:0);if(output==MediaCodec.INFO_TRY_AGAIN_LATER){if(!end||android.os.SystemClock.elapsedRealtime()>deadline)break;continue;}if(output==MediaCodec.INFO_OUTPUT_FORMAT_CHANGED){if(muxerStarted)throw new IOException("Audio format changed");track=muxer.addTrack(encoder.getOutputFormat());muxer.start();muxerStarted=true;continue;}if(output<0)continue;ByteBuffer buffer=encoder.getOutputBuffer(output);if((info.flags&MediaCodec.BUFFER_FLAG_CODEC_CONFIG)!=0)info.size=0;if(info.size>0&&muxerStarted){buffer.position(info.offset);buffer.limit(info.offset+info.size);muxer.writeSampleData(track,buffer,info);}boolean done=(info.flags&MediaCodec.BUFFER_FLAG_END_OF_STREAM)!=0;encoder.releaseOutputBuffer(output,false);if(done)break;}}
  boolean finish(){finishing=true;CountDownLatch done=new CountDownLatch(1);worker.post(()->{try{if(!failed){int index=encoder.dequeueInputBuffer(100000);if(index<0)throw new IOException("Audio EOS unavailable");encoder.queueInputBuffer(index,0,0,Math.max(0,lastPts+64000),MediaCodec.BUFFER_FLAG_END_OF_STREAM);drain(true);}}catch(Exception e){failed=true;Log.w("BloubMonitor","Audio finish",e);}finally{try{encoder.stop();}catch(Exception ignored){}encoder.release();try{if(muxerStarted)muxer.stop();}catch(Exception e){failed=true;}finally{muxer.release();thread.quitSafely();done.countDown();}}});try{if(!done.await(5,TimeUnit.SECONDS)){failed=true;return false;}}catch(InterruptedException e){Thread.currentThread().interrupt();failed=true;}return !failed&&samples>0&&file.length()>1024;}
}
